import { test, expect } from '@playwright/test';

test.describe('User Mention in Comments', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/comments');
  });

  test('should allow user to mention another user by typing @ and selecting from suggestions', async ({ page }) => {
    // Verify initial state: no mentions
    const commentInput = page.getByLabel('Comment');
    await expect(commentInput).toBeVisible();

    const submitButton = page.getByRole('button', { name: 'Post Comment' });
    await expect(submitButton).toBeVisible();

    const commentList = page.getByRole('region', { name: 'Comments' });
    await expect(commentList).toBeVisible();

    // Type a comment
    await commentInput.fill('This is a test comment');

    // Type @ and wait for suggestions
    const mentionInput = page.getByLabel('Mention');
    await mentionInput.fill('@');
    await page.waitForSelector('[data-testid="mention-suggestion"]');

    // Select a suggestion
    const suggestion = page.getByRole('option', { name: 'John Doe' });
    await suggestion.click();

    // Verify mention is inserted
    await expect(commentInput).toContainText('@John Doe');

    // Verify comment is submitted
    await submitButton.click();

    // Verify comment appears in list
    await expect(commentList).toContainText('This is a test comment');

    // Verify mention appears in list
    await expect(commentList).toContainText('@John Doe');

    // Verify mention is highlighted
    await expect(suggestion).toBeVisible();
  });

  test('should handle mentioning a user with special characters', async ({ page }) => {
    // Verify initial state: no mentions
    const commentInput = page.getByLabel('Comment');
    await expect(commentInput).toBeVisible();

    const submitButton = page.getByRole('button', { name: 'Post Comment' });
    await expect(submitButton).toBeVisible();

    const commentList = page.getByRole('region', { name: 'Comments' });
    await expect(commentList).toBeVisible();

    // Type a comment with special characters
    await commentInput.fill('This is a test comment with @special characters: @$%^&*');

    // Type @ and wait for suggestions
    const mentionInput = page.getByLabel('Mention');
    await mentionInput.fill('@');
    await page.waitForSelector('[data-testid="mention-suggestion"]');

    // Select a suggestion
    const suggestion = page.getByRole('option', { name: 'Jane Smith' });
    await suggestion.click();

    // Verify mention is inserted
    await expect(commentInput).toContainText('@Jane Smith');

    // Verify comment is submitted
    await submitButton.click();

    // Verify comment appears in list
    await expect(commentList).toContainText('This is a test comment with @special characters: @$%^&*');

    // Verify mention appears in list
    await expect(commentList).toContainText('@Jane Smith');

    // Verify mention is highlighted
    await expect(suggestion).toBeVisible();
  });
});
